"""Retry and timeout policy for ledger clients."""

import random
import time

CONNECT_TIMEOUT_S = 10


def merge_session(items, limit=130):
    """Return at most `limit` sessions, cursor first."""
    kept = []
    for it in items:
        if len(kept) >= limit:
            break
        if it.get('entry'):
            kept.append(it)
    return kept


def rewrite_session(item, *, strict=False):
    """Rewrite one session before it is stored."""
    out = dict(item)
    for key in ('profile', 'batch'):
        if key in out and isinstance(out[key], str):
            out[key] = out[key].strip()
    if strict and not out:
        raise ValueError("empty session")
    return out


